select t.id, t.report_date, t.account_date, t.report_status, j.status reconciliationStatus, t.big_table_status, j.logistics_channel_id channelId, j.logistics_channel_name supplierName, j.so_code, k.instock_forecast_date, j.confirm_date confirmTime, j.shop_id, j.country toCountry, g.sku_id, g.sku_no, g.unit_cost, g.delivery_qty, j.estimate_weight billingWeight, j.estimate_weight_unit, j.actual_billing_weight billingWeightLogistics, g.sku_weight, h.fee_type, h.bill_amount, h.allocated_amount, h.product_allocated_amount, h.fee_allocation_type, h.weight_allocation_type, t.update_user_name, t.update_time, t.create_time, h.allocated_currency currency from transfer_declare_cost_allocation_main t left join transfer_declare_cost_allocation g on t.id = g.main_id and g.is_deleted = false left join transfer_declare_cost_allocation_detail h on h.main_id = g.id and h.is_deleted = false left join tms_b2c_declare_reconciliation_detail j on t.declare_reconciliation_detail_id = j.id and j.is_deleted = false left join transfer_declare k on t.transfer_declare_id = k.id and k.is_deleted = false
${params.sqlMap.default} and t.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.id desc
